import 'package:flutter/services.dart';

/// Channel names auto-generated by YouTube Music end in " - Topic".
String cleanYtUploaderName(String? raw) {
  final name = (raw ?? '').trim();
  const suffix = ' - Topic';
  if (name.endsWith(suffix) && name.length > suffix.length) {
    return name.substring(0, name.length - suffix.length).trim();
  }
  return name;
}

String? _nonEmpty(Object? value) {
  final s = value?.toString().trim() ?? '';
  return s.isEmpty ? null : s;
}

int? _positiveInt(Object? value) {
  final n = (value as num?)?.toInt();
  return n == null || n <= 0 ? null : n;
}

/// Audio-only stream resolved on the device, plus the video's metadata. The URL
/// is signed for this device's IP and expires: never persist it or log it.
class YtStreamResult {
  /// 11-character video id; empty only if the platform side did not send it.
  final String videoId;
  final String url;
  final String mimeType;
  final int itag;
  final double? bitrateKbps;
  final int? contentLength;

  /// Epoch seconds from the URL `expire` parameter, or null.
  final int? expiresAt;
  final int? durationSeconds;
  final Map<String, String> httpHeaders;
  final String title;

  /// Channel name, without the " - Topic" suffix.
  final String uploader;
  final String? thumbnailUrl;

  const YtStreamResult({
    this.videoId = '',
    required this.url,
    required this.mimeType,
    required this.itag,
    required this.bitrateKbps,
    required this.contentLength,
    required this.expiresAt,
    required this.durationSeconds,
    required this.httpHeaders,
    this.title = '',
    this.uploader = '',
    this.thumbnailUrl,
  });

  factory YtStreamResult.fromMap(Map<Object?, Object?> map) {
    final rawHeaders = map['httpHeaders'];
    return YtStreamResult(
      videoId: (map['videoId'] ?? '').toString(),
      url: (map['url'] ?? '').toString(),
      mimeType: (map['mimeType'] ?? '').toString(),
      itag: (map['itag'] as num?)?.toInt() ?? -1,
      bitrateKbps: (map['bitrateKbps'] as num?)?.toDouble(),
      contentLength: (map['contentLength'] as num?)?.toInt(),
      expiresAt: (map['expiresAt'] as num?)?.toInt(),
      durationSeconds: (map['durationSeconds'] as num?)?.toInt(),
      httpHeaders: rawHeaders is Map
          ? {for (final e in rawHeaders.entries) e.key.toString(): e.value.toString()}
          : const {},
      title: (map['title'] ?? '').toString().trim(),
      uploader: cleanYtUploaderName(map['uploader']?.toString()),
      thumbnailUrl: _nonEmpty(map['thumbnailUrl']),
    );
  }
}

/// A video from a search or a playlist listing. Not resolved: fetch the stream
/// with [HeardyYtStream.resolve] before downloading.
class YtVideoItem {
  final String id;
  final String title;

  /// Channel name, without the " - Topic" suffix.
  final String uploader;

  /// Null when the listing did not report it.
  final int? durationSeconds;
  final String? thumbnailUrl;
  final String url;

  const YtVideoItem({
    required this.id,
    required this.title,
    required this.uploader,
    required this.durationSeconds,
    required this.thumbnailUrl,
    required this.url,
  });

  /// Null when [raw] is not a map or has no id.
  static YtVideoItem? tryFromMap(Object? raw) {
    if (raw is! Map) return null;
    final id = (raw['id'] ?? '').toString().trim();
    if (id.isEmpty) return null;
    return YtVideoItem(
      id: id,
      title: (raw['title'] ?? '').toString().trim(),
      uploader: cleanYtUploaderName(raw['uploader']?.toString()),
      durationSeconds: _positiveInt(raw['durationSeconds']),
      thumbnailUrl: _nonEmpty(raw['thumbnailUrl']),
      url: _nonEmpty(raw['url']) ?? 'https://www.youtube.com/watch?v=$id',
    );
  }
}

List<YtVideoItem> _parseItems(Object? raw) =>
    raw is List ? raw.map(YtVideoItem.tryFromMap).whereType<YtVideoItem>().toList() : const [];

class YtPlaylist {
  final String id;
  final String name;
  final String url;
  final List<YtVideoItem> entries;

  const YtPlaylist({required this.id, required this.name, required this.url, required this.entries});

  factory YtPlaylist.fromMap(Map<Object?, Object?> map) => YtPlaylist(
        id: (map['id'] ?? '').toString(),
        name: (map['name'] ?? '').toString().trim(),
        url: (map['url'] ?? '').toString(),
        entries: _parseItems(map['entries']),
      );
}

/// Error codes of the [PlatformException]s thrown by [HeardyYtStream].
abstract final class YtStreamErrorCode {
  /// The video or playlist does not exist, is private, or is blocked.
  static const unavailable = 'unavailable';
  static const extractionFailed = 'extraction_failed';
  static const poTokenFailed = 'po_token_failed';

  /// The input is neither a video id nor a YouTube / YouTube Music URL of the expected kind.
  static const invalidUrl = 'invalid_url';
}

class HeardyYtStream {
  static const MethodChannel _channel = MethodChannel('heardy_yt_stream');

  static const int maxSearchLimit = 200;
  static const int defaultMaxPlaylistEntries = 10000;

  /// [input] is an 11-character video id or a YouTube / YouTube Music video URL.
  /// Throws [PlatformException] with a [YtStreamErrorCode] code.
  static Future<YtStreamResult> resolve(String input) async {
    final map = await _channel.invokeMapMethod<Object?, Object?>('resolve', {'input': input});
    if (map == null) {
      throw PlatformException(code: YtStreamErrorCode.extractionFailed, message: 'empty result');
    }
    return YtStreamResult.fromMap(map);
  }

  /// Videos only (no channels, playlists, live streams or shorts). [music]
  /// searches YouTube Music songs instead of regular videos.
  static Future<List<YtVideoItem>> search(String query, {int limit = 20, bool music = false}) async {
    final q = query.trim();
    if (q.isEmpty) return const [];
    final raw = await _channel.invokeMethod<Object?>(
      'search',
      {'query': q, 'limit': limit.clamp(1, maxSearchLimit), 'music': music},
    );
    return _parseItems(raw);
  }

  /// Expands a YouTube / YouTube Music playlist URL, following pagination up to [maxEntries].
  static Future<YtPlaylist> playlist(String url, {int maxEntries = defaultMaxPlaylistEntries}) async {
    final map = await _channel.invokeMapMethod<Object?, Object?>('playlist', {'url': url, 'maxEntries': maxEntries});
    if (map == null) {
      throw PlatformException(code: YtStreamErrorCode.extractionFailed, message: 'empty result');
    }
    return YtPlaylist.fromMap(map);
  }
}
